// 2:1 multiplexer (register -> register -> register, no feedback)
module TopModule (
    input [2:0] r,
    input L,
    input clk,
    output reg [2:0] q,
    input q_in,
    input r_in
);
    reg [2:0] q2;
    reg [2:0] q3;
    always @(posedge clk) begin
        if (L) begin
            q <= r;
            q2 <= r;
            q3 <= r;
        end else begin
            q <= {q[1] ^ q[2], q[0], q[2]};
            q2 <= {q2[1] ^ q2[2], q2[0], q2[2]};
            q3 <= {q3[1] ^ q3[2], q3[0], q3[2]};
        end
    end
    assign q_in = q;
    assign r_in = {q[1] ^ q[2], q[0], q[2]};
endmodule

