// One stage of the FF stage chain, with the select signal internally
// named "s" and the feedback multiplexed to go to the next stage.
module TopModule (
    input [2:0] r,
    input L,
    input clk,
    output reg [2:0] q);
  wire [2:0] q2;
  reg [2:0] s;
  always @(posedge clk) begin
    if (L) begin
      q <= r;
    end else begin
      q <= {q[1] ^ q[2], q[0], q2[2]};
    end
    s <= {q[1] ^ q[2], q[0], q2[2]};
  end
  full_module ff2 (.r(r), .L(L), .clk(clk), .q(q2));
  full_module ff3 (.r(r), .L(L), .clk(clk), .q(q2[2]));
endmodule

